-- club_fulfillment_queue: from 20261110000000_club_welcome_kit_approvals.sql, with the replacements listed in scripts/generate-welcome-rhythm-kit-migration.py
create view public.club_fulfillment_queue with (security_invoker = true) as
select o.id, o.user_id, o.household_id, o.resource_month, o.kit_id, k.slug as kit_slug, k.title as kit_title,
       o.status, o.late, o.cutoff_at, o.pdf_status, o.member_approved_at, o.printed_at, o.mailed_at, o.provider,
       o.provider_ref, o.note, o.created_at, o.updated_at,
       h.display_name, u.email,
       case
         when o.status not in ('pending', 'approved', 'on_hold') then o.status
         when kit.in_kit then case
           when kit.m_id is null then 'first_month_canceled'
           when h.onboarded_at is null then 'needs_profile'
           when a.user_id is null then 'needs_address'
           when a.paused then 'mail_paused'
           when not public.club_vision_valid(kit.w_personalization) or kit.w_approved_at is null then 'needs_vision'
           when mk.id is null or mk.status = 'draft' then 'needs_resource'
           when kit.m_approved_at is null then 'needs_confirmation'
           when kit.w_pdf <> 'ready' or kit.m_pdf <> 'ready' then 'needs_pdf'
           else 'ready' end
         when o.fulfillment_type = 'welcome_vision' and (not public.club_vision_valid(o.personalization) or o.member_approved_at is null) then 'needs_vision'
         when o.fulfillment_type = 'monthly_resource' and h.onboarded_at is null then 'needs_profile'
         when a.user_id is null then 'needs_address'
         when a.paused then 'mail_paused'
         when o.fulfillment_type = 'monthly_resource' and (k.id is null or k.status = 'draft') then 'needs_resource'
         when o.pdf_status <> 'ready' then 'needs_pdf'
         else 'ready' end as readiness,
       coalesce(o.address, l.address) as address,
       l.address as live_address,
       o.fulfillment_type,
       o.satisfies_month,
       o.personalization,
       case when kit.in_kit then 'welcome_kit' when o.fulfillment_type = 'welcome_vision' then 'welcome' when o.late then 'catch_up' else 'regular' end as batch,
       h.first_paid_month,
       h.enrolled_at,
       -- The Welcome Kit: whether this order ships in one, the other order in it, and when her first resource counts
       -- as confirmed without her (three days after she approved her print).
       kit.in_kit as in_welcome_kit,
       case when o.fulfillment_type = 'welcome_vision' then kit.m_id else kit.w_id end as kit_partner_id,
       -- Retired (20261110): nothing counts as confirmed without her. Kept, always null, for older readers.
       null::timestamptz as kit_auto_approve_at,
       -- Submitted: both of her approvals are in (print and first resource). The two-business-day target runs from here.
       case when kit.in_kit and kit.w_approved_at is not null and kit.m_approved_at is not null
            then greatest(kit.w_approved_at, kit.m_approved_at) end as kit_submitted_at,
       case when kit.in_kit and kit.w_approved_at is not null and kit.m_approved_at is not null
            then public.club_business_days_after(greatest(kit.w_approved_at, kit.m_approved_at), 2) end as kit_ship_by,
       h.meeting_guide_seen_at
  from public.club_fulfillment_orders o
  join public.club_households h on h.id = o.household_id
  join auth.users u on u.id = o.user_id
  left join public.club_kits k on k.id = o.kit_id
  left join public.club_mailing_addresses a on a.user_id = o.user_id
  left join lateral (select case when a.user_id is not null then jsonb_build_object('name', a.name, 'line1', a.line1, 'line2', a.line2,
    'city', a.city, 'state', a.state, 'postal_code', a.postal_code, 'country', a.country) end as address) l on true
  -- The welcome order a first-month monthly order ships with.
  left join lateral (select w.* from public.club_fulfillment_orders w
     where o.fulfillment_type = 'monthly_resource' and o.resource_month = h.first_paid_month
       and w.household_id = o.household_id and w.fulfillment_type = 'welcome_vision' and w.status <> 'canceled' and w.satisfies_month is null
     limit 1) kw on true
  -- The first-month monthly order a welcome print ships with (none: canceled, so the kit is held).
  left join lateral (select m.* from public.club_fulfillment_orders m
     where o.fulfillment_type = 'welcome_vision' and o.satisfies_month is null
       and m.household_id = o.household_id and m.fulfillment_type = 'monthly_resource' and m.resource_month = h.first_paid_month
       and m.status <> 'canceled'
     limit 1) km on true
  left join lateral (select
       (o.fulfillment_type = 'welcome_vision' and o.satisfies_month is null) or kw.id is not null as in_kit,
       case when o.fulfillment_type = 'welcome_vision' then o.id else kw.id end as w_id,
       case when o.fulfillment_type = 'welcome_vision' then o.personalization else kw.personalization end as w_personalization,
       case when o.fulfillment_type = 'welcome_vision' then o.member_approved_at else kw.member_approved_at end as w_approved_at,
       case when o.fulfillment_type = 'welcome_vision' then o.pdf_status else kw.pdf_status end as w_pdf,
       case when o.fulfillment_type = 'monthly_resource' then o.id else km.id end as m_id,
       case when o.fulfillment_type = 'monthly_resource' then o.member_approved_at else km.member_approved_at end as m_approved_at,
       case when o.fulfillment_type = 'monthly_resource' then o.pdf_status else km.pdf_status end as m_pdf,
       case when o.fulfillment_type = 'monthly_resource' then o.kit_id else km.kit_id end as m_kit) kit on true
  left join public.club_kits mk on mk.id = kit.m_kit;

-- club_admin_set_welcome_kit: from 20261110000000_club_welcome_kit_approvals.sql, with the replacements listed in scripts/generate-welcome-rhythm-kit-migration.py
create or replace function public.club_admin_set_welcome_kit(p_order uuid, p_status text, p_note text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  q record;
  w uuid;
  m uuid;
  ws text;
  ms text;
begin
  if not public.is_admin('owner') then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into q from public.club_fulfillment_queue where id = p_order;
  if not found then raise exception 'not_found'; end if;
  if not q.in_welcome_kit then raise exception 'not_a_kit'; end if;
  w := case when q.fulfillment_type = 'welcome_vision' then q.id else q.kit_partner_id end;
  m := case when q.fulfillment_type = 'welcome_vision' then q.kit_partner_id else q.id end;
  perform 1 from public.club_fulfillment_orders where id in (w, m) order by id for update;
  select status into ws from public.club_fulfillment_orders where id = w;
  if m is null then
    if p_status in ('approved', 'printed', 'mailed') and nullif(btrim(coalesce(p_note, '')), '') is null then raise exception 'note_required'; end if;
    perform set_config('club.kit_print_alone', 'on', true);
    perform public.club_admin_set_fulfillment(w, p_status, p_note, null);
    perform set_config('club.kit_print_alone', '', true);
    return (select to_jsonb(x) from public.club_fulfillment_queue x where x.id = w);
  end if;
  select status into ms from public.club_fulfillment_orders where id = m;
  if ws <> ms then raise exception 'kit_out_of_sync'; end if;
  perform set_config('club.kit_move', 'on', true);
  perform public.club_admin_set_fulfillment(w, p_status, p_note, null);
  perform public.club_admin_set_fulfillment(m, p_status, p_note, null);
  perform set_config('club.kit_move', '', true);
  perform public.admin_log('club.welcome_kit', 'club_order:' || w::text, jsonb_build_object('to', p_status, 'first_month_order', m));
  return (select to_jsonb(x) from public.club_fulfillment_queue x where x.id = w);
end $$;

-- club_admin_welcome_queue: from 20261110000000_club_welcome_kit_approvals.sql, with the replacements listed in scripts/generate-welcome-rhythm-kit-migration.py
create or replace function public.club_admin_welcome_queue() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_admin('owner') then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(to_jsonb(q) - 'personalization' || jsonb_build_object(
                     'vision_value', q.personalization ->> 'value', 'family_name', q.personalization ->> 'family_name',
                     'first_month', (select jsonb_build_object('id', p.id, 'resource_month', p.resource_month, 'kit_slug', p.kit_slug,
                        'kit_title', p.kit_title, 'status', p.status, 'pdf_status', p.pdf_status, 'member_approved_at', p.member_approved_at)
                        from public.club_fulfillment_queue p where p.id = q.kit_partner_id),
                     'packing_list', case when q.in_welcome_kit then jsonb_build_array(
                        'Family Vision print (personalized)', 'Family Meeting guide (standard insert)',
                        coalesce(to_char((select p.resource_month from public.club_fulfillment_queue p where p.id = q.kit_partner_id), 'FMMonth YYYY') || ' resource (personalized)', 'First month resource (personalized)'))
                        else jsonb_build_array('Family Vision print (personalized)') end)
                   order by q.kit_ship_by nulls last, q.created_at)
                     from public.club_fulfillment_queue q
                    where q.fulfillment_type = 'welcome_vision' and q.status not in ('mailed', 'canceled', 'skipped')), '[]');
end $$;

-- club_email_audience: from 20261110000000_club_welcome_kit_approvals.sql, with the replacements listed in scripts/generate-welcome-rhythm-kit-migration.py
create or replace function public.club_email_audience(p_kind text, p_month date default null) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(x), '[]') from (
    select h.owner_user_id as user_id, u.email, null::text as kit_slug, null::uuid as order_id, null::int as reminder
      from public.club_households h join auth.users u on u.id = h.owner_user_id
     where p_kind = 'profile_reminder' and h.onboarded_at is null and h.enrolled_at < now() - interval '1 day'
       and public.club_has_access(h.owner_user_id)
    union all
    select e.user_id, u.email, k.slug, null, null
      from public.club_entitlements e join auth.users u on u.id = e.user_id join public.club_kits k on k.month = e.resource_month
     where p_kind = 'resource_ready' and e.resource_month = p_month and e.kind = 'digital' and e.revoked_at is null
       and e.fulfilled_by = 'monthly_resource' and k.status in ('scheduled', 'retired')
    union all
    select q.user_id, q.email, q.kit_slug, q.id, null
      from public.club_fulfillment_queue q
     where p_kind = 'review' and q.resource_month = p_month and q.status = 'pending' and q.member_approved_at is null
       and q.fulfillment_type = 'monthly_resource' and not q.in_welcome_kit and q.readiness in ('ready', 'needs_pdf')
    union all
    select q.user_id, q.email, p.kit_slug, q.id, case when now() >= q.member_approved_at + interval '7 days' then 2 else 1 end
      from public.club_fulfillment_queue q join public.club_fulfillment_queue p on p.id = q.kit_partner_id
     where p_kind = 'kit_reminder' and q.fulfillment_type = 'welcome_vision' and q.status = 'pending'
       and q.readiness = 'needs_confirmation' and now() >= q.member_approved_at + interval '2 days'
  ) x;
$$;

-- club_kit_submitted: from 20261110000000_club_welcome_kit_approvals.sql, with the replacements listed in scripts/generate-welcome-rhythm-kit-migration.py
create or replace function public.club_kit_submitted(p_user uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('order_id', q.id, 'email', q.email, 'family_name', coalesce(q.personalization ->> 'family_name', q.display_name),
           'first_month', (select p.resource_month from public.club_fulfillment_queue p where p.id = q.kit_partner_id),
           'submitted_at', q.kit_submitted_at, 'ship_by', q.kit_ship_by)
    from public.club_fulfillment_queue q
   where q.user_id = p_user and q.fulfillment_type = 'welcome_vision' and q.in_welcome_kit and q.kit_submitted_at is not null
     and q.status in ('pending', 'approved') and q.readiness in ('needs_pdf', 'ready')
   order by q.created_at limit 1;
$$;

-- club_me: from 20261107000000_club_first_month_free.sql, with the replacements listed in scripts/generate-welcome-rhythm-kit-migration.py
create or replace function public.club_me() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  uid uuid := auth.uid();
  s public.club_subscriptions%rowtype;
  h public.club_households%rowtype;
  cur date := public.club_month_of(now());
  last_owned date;
  next_month date;
begin
  if uid is null then raise exception 'not_signed_in'; end if;
  select * into s from public.club_subscriptions where user_id = uid order by (status in ('trialing', 'active', 'past_due', 'unpaid', 'paused')) desc, created_at desc limit 1;
  select * into h from public.club_households where owner_user_id = uid;
  select max(e.resource_month) into last_owned from public.club_entitlements e where e.user_id = uid and e.kind = 'digital' and e.revoked_at is null;
  next_month := coalesce((last_owned + interval '1 month')::date, public.club_month_of(s.current_period_end));
  return jsonb_build_object(
    'access', public.club_has_access(uid),
    -- Her free first month (one per household), and when it ends.
    'intro', (select jsonb_build_object('month', i.intro_month, 'trial_ends', case when s.status = 'trialing' then s.current_period_end end)
                from public.club_intro_claims i where i.user_id = uid and i.revoked_at is null order by i.claimed_at desc limit 1),
    'grant', (select g.reason from public.club_access_grants g
               where g.user_id = uid and g.revoked_at is null and (g.expires_at is null or g.expires_at > now())),
    'member', h.enrolled_at is not null or coalesce(s.status in ('trialing', 'active', 'past_due'), false),
    'plan', s.plan,
    'status', s.status,
    'payment_problem', s.status in ('past_due', 'unpaid', 'incomplete'),
    'renews', case when s.status in ('trialing', 'active', 'past_due') and not s.cancel_at_period_end then s.current_period_end end,
    'ends', case when s.cancel_at_period_end and s.status in ('trialing', 'active', 'past_due') then s.current_period_end end,
    'ended_at', s.ended_at,
    'revoked', s.access_revoked_at is not null,
    'onboarded', h.onboarded_at is not null,
    'has_address', exists (select 1 from public.club_mailing_addresses a where a.user_id = uid),
    'enrolled_at', h.enrolled_at,
    'first_paid_month', h.first_paid_month,
    'current_month', cur,
    'membership_year', case when h.first_paid_month is not null then public.club_membership_year(h.first_paid_month, greatest(cur, h.first_paid_month)) end,
    'kits', coalesce((
      select jsonb_agg(jsonb_build_object('slug', k.slug, 'title', k.title, 'month', k.month,
                                          'can', public.club_can_open(uid, k.id)) order by k.month desc)
        from public.club_kits k where public.club_can_open(uid, k.id) <> 'none'), '[]'),
    'welcome', (select jsonb_build_object('status', q.status, 'readiness', q.readiness, 'approved', q.member_approved_at is not null,
                  'personalized', public.club_vision_valid(q.personalization), 'satisfies_month', q.satisfies_month, 'mailed_at', q.mailed_at)
                  from public.club_fulfillment_queue q where q.user_id = uid and q.fulfillment_type = 'welcome_vision' and q.status <> 'canceled' limit 1),
    -- The next month she'd receive, and when it's paid for (only while the membership continues).
    -- A founding member who holds no month yet: the month her first membership payment buys.
    'next', case when s.status in ('trialing', 'active', 'past_due') and not s.cancel_at_period_end
                  and next_month is not null then
              jsonb_build_object('month', next_month, 'payment_on', s.current_period_end,
                'slug', (select k.slug from public.club_kits k where k.month = next_month),
                'title', (select k.title from public.club_kits k where k.month = next_month),
                'regular_cutoff_at', public.club_mailing_cutoff_at(next_month)) end,
    -- Only the months she has bought, each with what fulfills it and its printed copy.
    'months', coalesce((
      select jsonb_agg(r order by (r ->> 'month')) from (
        select jsonb_build_object(
          'month', d.resource_month,
          'fulfilled_by', d.fulfilled_by,
          'free', d.source = 'intro',
          'slug', k.slug, 'title', k.title,
          'published', coalesce(k.status in ('scheduled', 'retired'), false),
          'can', case when k.id is null or d.fulfilled_by <> 'monthly_resource' then 'none' else public.club_can_open(uid, k.id) end,
          'state', case
            when d.fulfilled_by = 'welcome_vision' then 'welcome_vision'
            when coalesce(k.status in ('scheduled', 'retired'), false) then 'available'
            else 'preparing' end,
          'membership_year', d.membership_year,
          'plan', d.plan,
          'mailing', (select jsonb_build_object('status', q.status, 'readiness', q.readiness, 'late', q.late, 'batch', q.batch,
                                                'approved', q.member_approved_at is not null, 'mailed_at', q.mailed_at)
                        from public.club_fulfillment_queue q where q.user_id = uid and q.resource_month = d.resource_month
                         and q.fulfillment_type = 'monthly_resource' and q.status <> 'canceled' limit 1)
        ) as r
        from public.club_entitlements d
        left join public.club_kits k on k.month = d.resource_month
        where d.user_id = uid and d.kind = 'digital' and d.revoked_at is null
      ) t), '[]'));
end $$;

-- club_admin_members: from 20261106000000_club_welcome_vision.sql, with the replacements listed in scripts/generate-welcome-rhythm-kit-migration.py
create or replace function public.club_admin_members(p_status text default null, p_month date default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_admin('owner') then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(x order by x ->> 'enrolled_at' desc nulls last) from (
    select jsonb_build_object(
      'user_id', h.owner_user_id, 'household_id', h.id, 'email', u.email, 'display_name', h.display_name,
      'enrolled_at', h.enrolled_at, 'first_paid_month', h.first_paid_month, 'onboarded', h.onboarded_at is not null,
      'adults', (select count(*) from public.club_family_members m where m.household_id = h.id and m.archived_at is null and m.kind = 'adult'),
      'children', (select count(*) from public.club_family_members m where m.household_id = h.id and m.archived_at is null and m.kind = 'child'),
      'child_birth_years', (select coalesce(jsonb_agg(m.birth_year order by m.birth_year), '[]') from public.club_family_members m where m.household_id = h.id and m.archived_at is null and m.kind = 'child'),
      'plan', s.plan, 'status', s.status, 'cancel_at_period_end', s.cancel_at_period_end, 'current_period_end', s.current_period_end,
      'ended_at', s.ended_at, 'livemode', s.livemode, 'flags', s.flags, 'revoked', s.access_revoked_at is not null,
      'stripe_customer_id', s.stripe_customer_id, 'stripe_subscription_id', s.stripe_subscription_id,
      'payment_problem', s.status in ('past_due', 'unpaid', 'incomplete') or exists (
        select 1 from public.club_invoices i where i.subscription_id = s.id and i.status = 'open' and i.attempt_count > 0),
      'months', (select coalesce(jsonb_agg(distinct e.resource_month order by e.resource_month), '[]') from public.club_entitlements e
                  where e.user_id = h.owner_user_id and e.kind = 'digital' and e.revoked_at is null),
      'welcome', (select jsonb_build_object('status', q.status, 'readiness', q.readiness, 'satisfies_month', q.satisfies_month, 'mailed_at', q.mailed_at)
                    from public.club_fulfillment_queue q where q.user_id = h.owner_user_id and q.fulfillment_type = 'welcome_vision' and q.status <> 'canceled' limit 1),
      'address', (select jsonb_build_object('name', a.name, 'line1', a.line1, 'line2', a.line2, 'city', a.city, 'state', a.state,
                                            'postal_code', a.postal_code, 'paused', a.paused) from public.club_mailing_addresses a where a.user_id = h.owner_user_id)
    ) as x
      from public.club_households h
      join auth.users u on u.id = h.owner_user_id
      left join lateral (select * from public.club_subscriptions s2 where s2.user_id = h.owner_user_id
                          order by (s2.status in ('trialing', 'active', 'past_due', 'unpaid', 'paused')) desc, s2.created_at desc limit 1) s on true
     where (p_status is null
            or (p_status = 'active' and s.status in ('active', 'trialing') and not s.cancel_at_period_end)
            or (p_status = 'canceling' and s.cancel_at_period_end and s.status in ('active', 'trialing', 'past_due'))
            or (p_status = 'problem' and s.status in ('past_due', 'unpaid', 'incomplete'))
            or (p_status = 'canceled' and s.status in ('canceled', 'incomplete_expired'))
            or (p_status = 'monthly' and s.plan = 'monthly') or (p_status = 'annual' and s.plan = 'annual')
            or (p_status = 'no_profile' and h.onboarded_at is null and h.enrolled_at is not null))
       and (p_month is null or exists (select 1 from public.club_entitlements e where e.user_id = h.owner_user_id
                                        and e.resource_month = p_month and e.revoked_at is null))
  ) t), '[]');
end $$;

-- club_admin_member_months: from 20261106000000_club_welcome_vision.sql, with the replacements listed in scripts/generate-welcome-rhythm-kit-migration.py
create or replace function public.club_admin_member_months(p_user uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_admin('owner') then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object(
    'welcome', (select jsonb_build_object('id', q.id, 'status', q.status, 'readiness', q.readiness, 'satisfies_month', q.satisfies_month,
                  'created_at', q.created_at, 'mailed_at', q.mailed_at, 'vision_value', q.personalization ->> 'value')
                  from public.club_fulfillment_queue q where q.user_id = p_user and q.fulfillment_type = 'welcome_vision'
                 order by (q.status = 'canceled'), q.created_at desc limit 1),
    'months', coalesce((select jsonb_agg(jsonb_build_object(
        'month', d.resource_month, 'fulfilled_by', d.fulfilled_by, 'kit_slug', k.slug, 'plan', d.plan, 'invoice', d.invoice_id,
        'source', d.source, 'membership_year', d.membership_year, 'revoked', d.revoked_at is not null, 'revoked_reason', d.revoked_reason,
        'mailing', (select jsonb_build_object('id', q.id, 'status', q.status, 'batch', q.batch, 'cutoff_at', q.cutoff_at, 'mailed_at', q.mailed_at)
                      from public.club_fulfillment_queue q where q.user_id = p_user and q.resource_month = d.resource_month
                       and q.fulfillment_type = 'monthly_resource' and q.status <> 'canceled' limit 1))
        order by d.resource_month, d.granted_at)
      from public.club_entitlements d left join public.club_kits k on k.id = d.kit_id
     where d.user_id = p_user and d.kind = 'digital'), '[]'));
end $$;

-- club_admin_fulfillment_bundle: from 20261106000000_club_welcome_vision.sql, with the replacements listed in scripts/generate-welcome-rhythm-kit-migration.py
create or replace function public.club_admin_fulfillment_bundle(p_order uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  o public.club_fulfillment_orders%rowtype;
begin
  if not public.is_admin('owner') then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into o from public.club_fulfillment_orders where id = p_order;
  if not found then raise exception 'not_found'; end if;
  perform public.admin_log('club.fulfillment_open', 'club_order:' || p_order::text, jsonb_build_object('month', o.resource_month, 'type', o.fulfillment_type));
  return jsonb_build_object(
    'order', (select to_jsonb(q) from public.club_fulfillment_queue q where q.id = p_order),
    'household', (select jsonb_build_object('id', h.id, 'display_name', h.display_name, 'preferences', h.preferences,
        'profile_version', h.profile_version, 'onboarded', h.onboarded_at is not null,
        'members', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'first_name', m.first_name, 'kind', m.kind, 'role', m.role,
            'is_account_holder', m.is_account_holder, 'birth_year', m.birth_year, 'birth_month', m.birth_month, 'archived', false) order by m.sort, m.created_at)
          from public.club_family_members m where m.household_id = h.id and m.archived_at is null), '[]'))
      from public.club_households h where h.id = o.household_id),
    'state', (select v.state from public.club_resource_versions v where v.household_id = o.household_id and v.kit_id = o.kit_id));
end $$;

-- club_welcome_plan_save: from 20261121000000_club_welcome_plans.sql, with the replacements listed in scripts/generate-welcome-rhythm-kit-migration.py
create or replace function public.club_welcome_plan_save(p_state jsonb, p_revision int) returns int
language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := auth.uid();
  h public.club_households%rowtype;
  rev int;
begin
  if uid is null then raise exception 'not_signed_in'; end if;
  if public.club_welcome_plan_access(uid) <> 'edit' then raise exception 'read_only'; end if;
  select * into h from public.club_households where owner_user_id = uid;
  if not found then raise exception 'no_household'; end if;
  if p_revision <> 0 and exists (select 1 from public.club_welcome_plans w where w.household_id = h.id and w.revision = p_revision and w.state = p_state) then
    return p_revision;
  end if;
  if p_revision = 0 then
    insert into public.club_welcome_plans (household_id, state) values (h.id, p_state)
      on conflict (household_id) do nothing returning revision into rev;
  else
    update public.club_welcome_plans set state = p_state, revision = revision + 1, approved_at = null, approved_fingerprint = null, updated_at = now()
     where household_id = h.id and revision = p_revision returning revision into rev;
  end if;
  if rev is null then raise exception 'conflict'; end if;
  return rev;
exception
  when check_violation or not_null_violation then raise exception 'invalid';
end $$;

-- club_welcome_plan_approve: from 20261121000000_club_welcome_plans.sql, with the replacements listed in scripts/generate-welcome-rhythm-kit-migration.py
create or replace function public.club_welcome_plan_approve(p_revision int, p_fingerprint text, p_state jsonb default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := auth.uid();
  h public.club_households%rowtype;
  n int;
begin
  if uid is null then raise exception 'not_signed_in'; end if;
  if public.club_welcome_plan_access(uid) <> 'edit' then raise exception 'read_only'; end if;
  if p_fingerprint is null or btrim(p_fingerprint) = '' then raise exception 'invalid'; end if;
  select * into h from public.club_households where owner_user_id = uid;
  if not found then raise exception 'no_household'; end if;
  if p_revision = 0 then
    if p_state is null then raise exception 'invalid'; end if;
    insert into public.club_welcome_plans (household_id, state, approved_at, approved_fingerprint)
      values (h.id, p_state, now(), p_fingerprint) on conflict (household_id) do nothing;
    get diagnostics n = row_count;
  else
    update public.club_welcome_plans set approved_at = now(), approved_fingerprint = p_fingerprint, updated_at = now()
     where household_id = h.id and revision = p_revision;
    get diagnostics n = row_count;
  end if;
  if n = 0 then raise exception 'conflict'; end if;
  return public.club_welcome_plan_get();
exception
  when check_violation or not_null_violation then raise exception 'invalid';
end $$;

-- club_welcome_plan_unapprove: from 20261121000000_club_welcome_plans.sql, with the replacements listed in scripts/generate-welcome-rhythm-kit-migration.py
create or replace function public.club_welcome_plan_unapprove(p_revision int) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := auth.uid();
  n int;
begin
  if uid is null then raise exception 'not_signed_in'; end if;
  if public.club_welcome_plan_access(uid) <> 'edit' then raise exception 'read_only'; end if;
  update public.club_welcome_plans w set approved_at = null, approved_fingerprint = null, updated_at = now()
    from public.club_households h where h.id = w.household_id and h.owner_user_id = uid and w.revision = p_revision;
  get diagnostics n = row_count;
  if n = 0 then raise exception 'conflict'; end if;
  return public.club_welcome_plan_get();
end $$;

